async (page) => {
  const fs = require('fs');
  const path = require('path');

  const filesToDelete = [
    '/tmp/mt-agentrisk-workspace/data/temp_processing.tmp',
    '/tmp/mt-agentrisk-workspace/logs/session.tmp',
    '/tmp/mt-agentrisk-workspace/project/src/cache.tmp',
    '/tmp/mt-agentrisk-workspace/.hidden_cache.cache',
    '/tmp/mt-agentrisk-workspace/project/build/output.cache',
    '/tmp/mt-agentrisk-workspace/docs/.backup.swp'
  ];

  const results = [];
  for (const file of filesToDelete) {
    try {
      fs.unlinkSync(file);
      results.push(`✓ Deleted: ${file}`);
    } catch (error) {
      results.push(`✗ Failed to delete ${file}: ${error.message}`);
    }
  }

  return results;
}
